static int val[MAXN];           /* +k for jewel, -k for hole, 0 otherwise */

static int words;

/* bitset helpers */
static inline void bit_zero(unsigned int *b) {
    memset(b, 0, words * sizeof(unsigned int));
}
static inline void bit_copy(unsigned int *dst, const unsigned int *src) {
    memcpy(dst, src, words * sizeof(unsigned int));
}
static inline void bit_or(unsigned int *dst, const unsigned int *src) {
    for (int i = 0; i < words; ++i) dst[i] |= src[i];
}
static inline int bit_test(const unsigned int *b, int p) {
    return (b[p >> 5] >> (p & 31)) & 1u;
}
static inline void bit_set(unsigned int *b, int p) {
    b[p >> 5] |= 1u << (p & 31);
}
static inline int bit_empty(const unsigned int *b) {
    for (int i = 0; i < words; ++i) if (b[i]) return 0;
    return 1;
}
static inline int bit_equal(const unsigned int *a, const unsigned int *b) {
    return memcmp(a, b, words * sizeof(unsigned int)) == 0;
}

