       reach[u][v] = exists path from u to v moving only right/down through non-walls */
    static int dp[MAXH][MAXW];
    for (int s = 0; s < N; ++s) {
        memset(dp, 0, sizeof(dp));
        int sx = x_of[s], sy = y_of[s];
        dp[sy][sx] = 1;
        for (int y = sy; y <= H; ++y) {
