                if ((x > 1 && dp[y][x - 1]) || (y > 1 && dp[y - 1][x])) dp[y][x] = 1;
            }
        }
        for (int t = 0; t < N; ++t) {
            reach[s][t] = dp[y_of[t]][x_of[t]];
        }
    }

    int start = id[1][1];
    int goal = id[H][W];

    /* For each node i, possible predecessors j with reach[j][i] and no other special node strictly between
       are not explicitly needed; we use interval DP on special nodes only. */

    /* collect special nodes (jewels/holes) plus start and goal */
    int special[MAXN], S = 0;
    int is_special[MAXN];
    memset(is_special, 0, sizeof(is_special));
    for (int i = 0; i < N; ++i) {
        if (val[i] != 0 || i == start || i == goal) {
            is_special[i] = 1;
            special[S++] = i;
        }
