    /* sort special by row-major id already in order because ids assigned row-major */
    /* DP over feasible stack states represented by top matched hole endpoint.
       State idea:
       choose a sequence of matched pairs (jewel -> corresponding hole) properly nested and monotone.
       Standard interval DP:
       best[u][v] = max number of matched pairs inside a path segment from u to v,
       assuming path can go from u to v.
    */
    static short best[MAXN][MAXN];
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            best[i][j] = -30000;

    for (int i = 0; i < N; ++i) {
        if (reach[i][i]) best[i][i] = 0;
    }

    /* process intervals in increasing order */
    for (int len = 1; len < N; ++len) {
        for (int l = 0; l + len < N; ++l) {
            int r = l + len;
            if (!reach[l][r]) continue;

            short ans = 0; /* skip all specials in between */
            /* split */
            for (int m = l; m < r; ++m) {
                if (reach[l][m] && reach[m][r]) {
                    short a = best[l][m];
                    short b = best[m][r];
                    if (a >= 0 && b >= 0 && a + b > ans) ans = a + b;
                }
            }

            /* match one outer pair p<q inside [l,r], nested */
            for (int p = l + 1; p <= r; ++p) {
                if (val[p] <= 0) continue; /* jewel */
                int k = val[p];
                for (int q = p; q <= r; ++q) {
                    if (val[q] != -k) continue; /* matching hole */
                    if (!(reach[l][p] && reach[p][q] && reach[q][r])) continue;

                    short left = best[l][p];
                    short mid = best[p][q];
                    short right = best[q][r];
                    if (left < 0 || mid < 0 || right < 0) continue;

                    /* To respect stack order, everything done inside (p,q) must be completed before q,
                       which interval nesting naturally enforces. */
                    short cand = left + mid + right + 1;
                    if (cand > ans) ans = cand;
                }
            }
            best[l][r] = ans;
        }
    }

    if (!reach[start][goal]) {
        printf("-1\n");
        return 0;
    }

    printf("%d\n", (int)best[start][goal]);
    return 0;
}

