int solve(int x, int y, string stk) {
    if (x == W-1 && y == H-1) return 0;
    auto key = make_tuple(x, y, stk);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;

    int res = -1;
    // Try moving right and down
    for (auto [nx, ny] : vector<pair<int,int>>{{x+1,y},{x,y+1}}) {
        if (nx >= W || ny >= H) continue;
        char c = grid[ny][nx];
        if (c == '#') continue;
        string nstk = stk;
        int gained = 0;
        if (islower(c)) {
            nstk.push_back(c);
        } else if (isupper(c)) {
            if (!nstk.empty() && nstk.back() == tolower(c)) {
                // Can place or not
                string placed_stk = nstk.substr(0, nstk.size()-1);
                int r1 = solve(nx, ny, placed_stk);
                if (r1 >= 0) res = max(res, r1 + 1);
                int r2 = solve(nx, ny, nstk);
                if (r2 >= 0) res = max(res, r2);
                continue;
            }
        }
        int r = solve(nx, ny, nstk);
        if (r >= 0) res = max(res, r + gained);
    }
    memo[key] = res;
    return res;
}

