import sys

def solve():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    W, H = map(int, data[0].split())
    grid = [list(data[i + 1].rstrip('\n')) for i in range(H)]

    NEG = -10**18

    # dp[j][mask]: best score at current row, column j (1-based in transitions)
    # after processing cell (j, current_row), with stack state = mask.
    # Stack is encoded in base-3 over jewel types a..j / A..J (up to 10 types):
    # digit 0 = absent, 1 = currently in stack, 2 = already matched and finished.
    #
    # This works because along any valid process with stack discipline, for each jewel type:
    # - not seen yet / irrelevant -> 0
    # - picked and not yet placed -> 1
    # - already placed -> 2
    #
    # Since each type appears at most once as jewel and once as hole (implied by statement style),
    # and retrieval is LIFO, the actual stack top among "1" states matters.
    # We reconstruct top by requiring transitions to respect nesting induced by path order.
    #
    # To make this precise, we encode actual stack order using ternary rank is insufficient in general.
    # So instead we instead keep full stack as a string over at most 10 types.
    #
    # Number of possible stacks is small: all subsets/permutations of up to 10 types => sum P(10,k) < 10^7,
    # too large globally, but reachable states on monotone path DP are typically tiny.
    # We'll use sparse DP with tuple stacks.

    # Rebuild with sparse DP over actual stack tuples.
    prev = [dict() for _ in range(W + 1)]
    # before starting, virtual position (0,1) impossible; initialize at first cell through transitions
    prev[0][()] = 0

    def process_cell(ch, stack, val):
        if ch == '#':
            return None
        if ch == '.' or not ch.isalpha():
            return (stack, val)
        if 'a' <= ch <= 'z':
            t = ord(ch) - ord('a')
            return (stack + (t,), val)
        if 'A' <= ch <= 'Z':
            t = ord(ch) - ord('A')
            if stack and stack[-1] == t:
                return (stack[:-1], val + 1)
            return None
        return (stack, val)

    for y in range(1, H + 1):
        cur = [dict() for _ in range(W + 1)]
        for x in range(1, W + 1):
            ch = grid[y - 1][x - 1]
            best = cur[x]
            # from left
            for st, v in cur[x - 1].items():
                res = process_cell(ch, st, v)
                if res is not None:
                    nst, nv = res
                    if nv > best.get(nst, NEG):
                        best[nst] = nv
            # from up
            for st, v in prev[x].items():
                res = process_cell(ch, st, v)
                if res is not None:
                    nst, nv = res
                    if nv > best.get(nst, NEG):
                        best[nst] = nv
        prev = cur

    ans_dict = prev[W]
    if not ans_dict:
        print(-1)
    else:
        print(max(ans_dict.values()))

