import java.io.*;
import java.util.*;

public class Main {
    static int W, H;
    static char[][] grid;
    // dp[r][c] maps stack string -> max placed jewels
    static HashMap<String, Integer>[][] dp;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        W = Integer.parseInt(st.nextToken());
        H = Integer.parseInt(st.nextToken());

        grid = new char[H][W];
        for (int i = 0; i < H; i++) {
            String line = br.readLine();
            for (int j = 0; j < W; j++) {
                grid[i][j] = line.charAt(j);
            }
        }

        if (grid[0][0] == '#' || grid[H-1][W-1] == '#') {
            System.out.println(-1);
            return;
        }

        dp = new HashMap[H][W];
        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                dp[i][j] = new HashMap<>();
            }
        }

        // Initialize start cell
        String startStack = "";
        int startPlaced = 0;
        char startChar = grid[0][0];
        if (startChar >= 'a' && startChar <= 'z') {
            startStack = "" + startChar;
        } else if (startChar >= 'A' && startChar <= 'Z') {
            // hole at start, cannot place anything, so just empty stack
            startStack = "";
        }
        dp[0][0].put(startStack, startPlaced);

        // Process cells in row-major order
        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                if (grid[r][c] == '#') continue;
                // Get states from top and left
                HashMap<String, Integer> curMap = new HashMap<>();
                if (r > 0) {
                    for (Map.Entry<String, Integer> e : dp[r-1][c].entrySet()) {
                        addState(curMap, e.getKey(), e.getValue());
                    }
                }
                if (c > 0) {
                    for (Map.Entry<String, Integer> e : dp[r][c-1].entrySet()) {
                        addState(curMap, e.getKey(), e.getValue());
                    }
                }
                // Also include start state if we are at (0,0)
                if (r == 0 && c == 0) {
                    curMap = dp[0][0];
                }
                // Now apply action at (r,c)
                char ch = grid[r][c];
                HashMap<String, Integer> newMap = new HashMap<>();
                for (Map.Entry<String, Integer> e : curMap.entrySet()) {
                    String stack = e.getKey();
                    int placed = e.getValue();
                    // Option: skip action (do nothing)
                    addState(newMap, stack, placed);
                    // Option: if jewel, pick it up
                    if (ch >= 'a' && ch <= 'z') {
                        String newStack = stack + ch;
                        addState(newMap, newStack, placed);
                    }
                    // Option: if hole and top matches, place
                    if (ch >= 'A' && ch <= 'Z') {
                        if (!stack.isEmpty() && stack.charAt(stack.length()-1) == (char)(ch + 32)) {
                            String newStack = stack.substring(0, stack.length()-1);
                            addState(newMap, newStack, placed + 1);
                        }
                    }
                }
                dp[r][c] = newMap;
            }
        }

        int maxPlaced = -1;
        for (int val : dp[H-1][W-1].values()) {
            if (val > maxPlaced) maxPlaced = val;
        }
        System.out.println(maxPlaced);
    }

    static void addState(HashMap<String, Integer> map, String stack, int placed) {
        if (map.containsKey(stack)) {
            if (placed > map.get(stack)) {
                map.put(stack, placed);
            }
        } else {
            map.put(stack, placed);
        }
    }
}

import java.io.*;
import java.util.*;

/*
We move from (1,1) to (W,H) only right/down.
Cells:
  '.' free
  '#' blocked
  'a'..'z' jewel
  'A'..'Z' hole for corresponding jewel

We carry jewels in a stack. Visiting a jewel pushes its type.
Visiting a hole may place a jewel only if the top of stack is the matching lowercase letter,
which pops it and increases score by 1.

We need maximum number of placed jewels among all valid monotone paths, or -1 if unreachable.

Key observation:
At any point, the only relevant bag state is the current stack content.
Since there are only 26 types, but path length can be large, we need pruning.

We use dynamic programming over cells with Pareto-optimal states:
for each reachable cell, keep a map:
   stackString -> maximum score for exactly this stack
If same stack appears with lower score, discard.
Additionally, dominance:
for same score, a stack that is suffix-easier? General dominance is hard.
But practical exact approach here uses hashing of stack strings.

Transition on character c:
  '.' : unchanged
  lowercase x : push x
  uppercase X :
      if stack nonempty and top == lowercase(X): pop and score+1
      else unchanged (you may pass without placing)

Because moves are only right/down, DP by rows works.

This is exact, though worst-case exponential; for contest constraints this style is intended when
grid sizes are moderate.

Input format assumed:
W H
H lines of length W

Coordinates in statement are 1-based with start top-left and goal bottom-right.
*/
public class Main {
    static class StateMap {
        HashMap<String, Integer> map = new HashMap<>();

        void putBetter(String stack, int val) {
            Integer old = map.get(stack);
            if (old == null || val > old) map.put(stack, val);
        }
    }

    static StateMap apply(StateMap src, char cell) {
        StateMap res = new StateMap();
        if (src == null) return null;
        for (Map.Entry<String, Integer> e : src.map.entrySet()) {
            String st = e.getKey();
            int val = e.getValue();
            if (cell == '.' || cell == '#') {
                res.putBetter(st, val);
            } else if (cell >= 'a' && cell <= 'z') {
                res.putBetter(st + cell, val);
            } else if (cell >= 'A' && cell <= 'Z') {
                char need = (char)(cell - 'A' + 'a');
                res.putBetter(st, val); // skip placing
                int n = st.length();
                if (n > 0 && st.charAt(n - 1) == need) {
                    res.putBetter(st.substring(0, n - 1), val + 1);
                }
            } else {
                res.putBetter(st, val);
            }
        }
        return res;
    }

    static StateMap merge(StateMap a, StateMap b) {
        if (a == null) return b;
        if (b == null) return a;
        if (a.map.size() < b.map.size()) {
            StateMap t = a; a = b; b = t;
        }
        for (Map.Entry<String, Integer> e : b.map.entrySet()) {
            a.putBetter(e.getKey(), e.getValue());
        }
        return a;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String first;
        while ((first = br.readLine()) != null && first.trim().isEmpty()) {}
        if (first == null) return;

        StringTokenizer st = new StringTokenizer(first);
        int W = Integer.parseInt(st.nextToken());
        int H = Integer.parseInt(st.nextToken());

        char[][] g = new char[H][W];
        for (int i = 0; i < H; i++) {
            String s = br.readLine();
            while (s != null && s.length() < W) {
                String t = br.readLine();
                if (t == null) break;
                s += t;
            }
            g[i] = s.toCharArray();
        }

        if (g[0][0] == '#' || g[H - 1][W - 1] == '#') {
            System.out.println(-1);
            return;
        }

        StateMap[] dp = new StateMap[W];

        for (int i = 0; i < H; i++) {
            StateMap left = null;
            for (int j = 0; j < W; j++) {
                if (g[i][j] == '#') {
                    dp[j] = null;
                    left = null;
                    continue;
                }

                StateMap from = null;
                if (i == 0 && j == 0) {
                    from = new StateMap();
                    from.putBetter("", 0);
                } else {
                    if (dp[j] != null) from = merge(from, dp[j]); // from top
                    if (left != null) from = merge(from, left);   // from left
                }

                StateMap cur = apply(from, g[i][j]);
                dp[j] = cur;
                left = cur;
            }
        }

        StateMap ansMap = dp[W - 1];
        if (ansMap == null || ansMap.map.isEmpty()) {
            System.out.println(-1);
            return;
        }

        int ans = -1;
        for (int v : ansMap.map.values()) ans = Math.max(ans, v);
        System.out.println(ans);
    }
}
